    pregnancyPhase: Object.freeze({ 孕早期: '孕早期（第一孕期）', 孕中期: '孕中期（第二孕期）', 孕晚期: '孕晚期（第三孕期）' }),
    conceptionOutcome: Object.freeze({ 待判定: '等待受孕判定', 已受孕: '受孕判定阳性', 未受孕: '受孕判定阴性' }),
