    const current = adapter?.getStore
      ? await adapter.getStore()
      : undefined;
    const base = isPlainObject(current) ? current : {};
    if (options.manualBase && JSON.stringify(base) !== JSON.stringify(options.manualBase)) throw new Error('状态刚刚发生变化，修改尚未保存，请刷新后重试。');
    const archives = options.archives ? sanitizeArchiveMap(options.archives) : sanitizeArchiveMap(base.archives);
