        const previousSnapshot = currentStore && Object.prototype.hasOwnProperty.call(currentStore,'snapshot')
          ? currentStore.has_valid_snapshot === true ? currentStore.snapshot : null : runtime.snapshot;
        const allowedNames = modelCharacterNames(currentStore);
        const effectEnabled = runtime.playLibraryEnabled
          || cyclePresenceActive(currentStore?.cycle_presence_enabled, effectiveModules)
